-- Deterministic reservation teams for the local application-review demo users.
insert into public.teams (id, name)
values
  ('00000000-0000-4000-8000-000000002001', 'Team Ada'),
  ('00000000-0000-4000-8000-000000002002', 'Team Grace')
on conflict (id) do update set name = excluded.name;

update public.users
set team_id = case id
  when '00000000-0000-4000-8000-000000000101' then
    '00000000-0000-4000-8000-000000002001'::uuid
  when '00000000-0000-4000-8000-000000000102' then
    '00000000-0000-4000-8000-000000002001'::uuid
  when '00000000-0000-4000-8000-000000000103' then
    '00000000-0000-4000-8000-000000002002'::uuid
  when '00000000-0000-4000-8000-000000000104' then
    '00000000-0000-4000-8000-000000002002'::uuid
end
where id in (
  '00000000-0000-4000-8000-000000000101',
  '00000000-0000-4000-8000-000000000102',
  '00000000-0000-4000-8000-000000000103',
  '00000000-0000-4000-8000-000000000104'
);
